      {circuitInfo.name}
      {#if circuitInfo.coordinates}
        <div style="font-size: 0.9em; color: #666; margin-top: 0.25rem;">
          📍 {circuitInfo.coordinates}
        </div>
      {/if}
    </span>
  </div>
